#pragma once
#include <stdint.h>
#include "../include/pfd_gfx.h"

/* Generated by tools/gen_font.py: 8-bit alpha glyphs sorted by code point. */
typedef struct {
    uint32_t cp;
    uint32_t off;
    uint8_t w, h;
    int8_t x0, y0;   /* offset from pen position / line top */
    uint8_t adv;
} pfd_glyph_t;

typedef struct {
    const pfd_glyph_t *glyphs;
    int count;
    const uint8_t *px;
    int line_h;
    int size;
} pfd_font_t;

extern const pfd_font_t pfd_fonts[PFD_FONT_COUNT];
